// Unchanged function excerpt; source identity is in core-v1-pilot.json.
// Only the required Linux LP64 header definitions are reproduced here.
typedef int fixed_t;
typedef long int64_t;
#define FRACBITS 16

fixed_t
FixedMul
( fixed_t	a,
  fixed_t	b )
{
    return ((int64_t) a * (int64_t) b) >> FRACBITS;
}
